import{_ as p,a0 as s,w as d,s as a,ao as l,I as r,x as e,a1 as u,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"如何启动 Ubuntu 22.04 进入救援/紧急模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何启动 Ubuntu 22.04 进入救援/紧急模式 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何启动 Ubuntu 22.04 进入救援/紧急模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何启动 Ubuntu 22.04 进入救援/紧急模式 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220607 How to Boot Ubuntu 22.04 into Rescue - Emergency Mode","title":"如何启动 Ubuntu 22.04 进入救援/紧急模式","tag":"202206","desc":""},"relativePath":"202206/20220607 How to Boot Ubuntu 22.04 into Rescue - Emergency Mode.md","filePath":"[post].md"}'),i={name:"202206/20220607 How to Boot Ubuntu 22.04 into Rescue - Emergency Mode.md"};function c(m,t,b,g,w,h){const o=s("Link");return d(),a("div",null,[t[15]||(t[15]=l('<h1 id="如何启动-ubuntu-22-04-进入救援-紧急模式" tabindex="-1">如何启动 Ubuntu 22.04 进入救援/紧急模式 <a class="header-anchor" href="#如何启动-ubuntu-22-04-进入救援-紧急模式" aria-label="Permalink to “如何启动 Ubuntu 22.04 进入救援/紧急模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/24/101647n4nru1ayaw4nrnue.jpg" alt=""></p><p>极客们好，将 Ubuntu 22.04（Jammy Jellyfish）启动到<ruby>救援<rt>Rescue</rt></ruby>和<ruby>紧急<rt>Emergency</rt></ruby>模式可以重置忘记的用户密码、修复文件系统错误，以及在启动过程中禁用或启用 systemd 服务。</p><p>在这篇文章中，我们将学习如何启动 Ubuntu 22.04 LTS 系统进入救援和应急模式。救援模式类似于单用户模式，所有的故障排除步骤都在这里进行。救援模式加载最小的环境并挂载根文件系统。</p><p>而在紧急模式下，我们得到的是单用户 Shell，而不启动任何系统服务。因此，当我们无法启动系统进入救援模式时，就需要紧急模式。</p><h3 id="启动-ubuntu-22-04-进入救援或单用户模式" tabindex="-1">启动 Ubuntu 22.04 进入救援或单用户模式 <a class="header-anchor" href="#启动-ubuntu-22-04-进入救援或单用户模式" aria-label="Permalink to “启动 Ubuntu 22.04 进入救援或单用户模式”">​</a></h3><p>前往你想启动到救援或单用户模式的目标系统。在启动时按下 <code>SHIFT + ESC</code> 键，进入 GRUB 引导加载器页面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Default-Grub-Screen-Ubuntu-22-04.png" alt="Default-Grub-Screen-Ubuntu-22-04"></p><p>选择第一个选项 “Ubuntu”，并按 <code>e</code> 键进入编辑模式。</p><p>在以 <code>linux</code> 开头的一行末尾，删除字符串 <code>$vt_handoff</code> 并添加字符串 <code>systemd.unit=rescue.target</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/rescue-target-ubuntu-22-04.png" alt="rescue-target-ubuntu-22-04"></p><p>做完修改后，按 <code>Ctrl + X</code> 或 <code>F10</code> 在救援模式下启动。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Troubleshooting-Commands-in-Rescue-Mode.png" alt="Troubleshooting-Commands-in-Rescue-Mode"></p><p>进入救援模式后，运行所有的故障排除命令，并运行 <code>systemctl reboot</code> 命令来重启系统。</p><h3 id="另一种启动系统进入救援模式的方法" tabindex="-1">另一种启动系统进入救援模式的方法 <a class="header-anchor" href="#另一种启动系统进入救援模式的方法" aria-label="Permalink to “另一种启动系统进入救援模式的方法”">​</a></h3><p>重新启动系统并按下 <code>ESC + Shift</code> 键，进入 GRUB 启动界面。</p><p>选择第二个选项 “<ruby>Ubuntu 高级选项<rt>Advanced Options for Ubuntu</rt></ruby>”-&gt;选择“<ruby>恢复模式<rt>recovery mode</rt></ruby>”选项并点击回车-&gt;选择 <ruby>root（进入 root shell 提示符）<rt>root (Drop to root shell prompt)</rt></ruby>。</p><p>下面是一个例子：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Boot-Ubuntu-22-04-Rescue-Mode.gif" alt="Boot-Ubuntu-22-04-Rescue-Mode"></p><p>当你有了 root Shell，运行命令来恢复和修复系统问题，最后使用 <code>systemctl reboot</code> 来重启系统。</p><h3 id="引导-ubuntu-22-04-进入紧急模式" tabindex="-1">引导 Ubuntu 22.04 进入紧急模式 <a class="header-anchor" href="#引导-ubuntu-22-04-进入紧急模式" aria-label="Permalink to “引导 Ubuntu 22.04 进入紧急模式”">​</a></h3><p>要启动系统进入紧急模式，首先进入 GRUB 页面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Default-Grub-Screen-Ubuntu-22-04.png" alt="Default-Grub-Screen-Ubuntu-22-04"></p><p>选择第一个选项 “Ubuntu” 并按 <code>e</code> 键进行编辑。寻找以 <code>linux</code> 开头的一行，移到该行的末尾，删除字符串 <code>$vt_handoff</code> 并添加字符串 <code>systemd.unit=emergency.target</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Emergency-Mode-Ubuntu-22-04.png" alt="Emergency-Mode-Ubuntu-22-04"></p><p>按 <code>Ctrl + X</code> 或 <code>F10</code> 将系统启动到紧急模式。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Command-in-Emergency-Mode-Ubuntu-22-04.png" alt="Command-in-Emergency-Mode-Ubuntu-22-04"></p><p>同样，在紧急模式下，你可以在这个模式下执行所有的故障排除，完成后，就用 <code>systemctl reboot</code> 命令重启系统。</p><p>这篇文章的内容就这些。文章内容丰富，不要犹豫，请在你的技术朋友中分享它。请在下面的评论区发表你的疑问和反馈。</p><hr>',30)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),u(o,{href:"https://www.linuxtechi.com/boot-ubuntu-22-04-rescue-emergency-mode/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.linuxtechi.com/boot-ubuntu-22-04-rescue-emergency-mode/",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=e("作者：",-1)),u(o,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...t[2]||(t[2]=[e("Pradeep Kumar",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),u(o,{href:"https://github.com/lkxed"},{default:n(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),u(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),u(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("本文由 ",-1)),u(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),u(o,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const x=p(i,[["render",c]]);export{U as __pageData,x as default};
